DEFINITIONSMALLAR = [
    "Vad är {q}?", "Vad menas med {b}?", "Vad betyder {b}?", "Kan du förklara {b}?",
    "Förklara {b}.", "Berätta om {b}.", "Vad innebär {b}?", "Vet du vad {q} är?", "{B}?",
    "Jag undrar vad {q} är.",
]
SKYDDSMALLAR = [
    "Hur skyddar jag mig mot {b}?", "Hur kan man skydda sig mot {b}?", "Hur undviker jag {b}?",
    "Vad kan jag göra mot {b}?", "Hur skyddar man sig mot {b}?", "Hur skyddar vi oss mot {b}?",
]


def varianter(fraga: str) -> list[str]:
    """Originalet plus en variant som den ofta skrivs i en chatt: gemener utan skiljetecken."""
    enkel = fraga.rstrip("?.!").lower()
    return [fraga] if enkel == fraga else [fraga, enkel]


def bygg() -> list[dict]:
    poster, sedda = [], set()

    def lagg_till(fraga: str, svar: str) -> None:
        for f in varianter(fraga):
            if (f, svar) not in sedda:
                sedda.add((f, svar))
                poster.append({"fråga": f, "svar": svar})

    for grund, vad_ar, forklaring, *skydd in BEGREPP:
        for mall in DEFINITIONSMALLAR:
            lagg_till(mall.format(q=vad_ar, b=grund, B=grund[0].upper() + grund[1:]), forklaring)
        if skydd:
            for mall in SKYDDSMALLAR:
                lagg_till(mall.format(b=grund), skydd[0])
    for fragor, svar in FRAGOR + SAMTAL:
        for f in fragor:
            lagg_till(f, svar)
    return poster


if __name__ == "__main__":
    ut = Path(__file__).resolve().parent.parent / "resources" / "datasets" / "svensk_cybersakerhet.jsonl"
    ut.parent.mkdir(parents=True, exist_ok=True)
    poster = bygg()
    with open(ut, "w", encoding="utf-8") as fh:
        for post in poster:
            fh.write(json.dumps(post, ensure_ascii=False) + "\n")
    svar = {p["svar"] for p in poster}
    print(f"{len(poster)} poster, {len(svar)} unika svar, "
          f"{sum(len(p['fråga']) + len(p['svar']) for p in poster):,} tecken → {ut}")
